steps.script:
var main = tree.current_scene
var H = load("res://tests/helpers/sw11e_s3_scen.gd")
return H.setup(1, {"cp": {"2": 0}})

var main = tree.current_scene
var H = load("res://tests/helpers/sw11e_s3_scen.gd")
PhaseManager.transition_to_phase(10)
return int(GameState.get_current_phase())

var main = tree.current_scene
var H = load("res://tests/helpers/sw11e_s3_scen.gd")
return H.frame(6, 31, 1.2)

var main = tree.current_scene
var H = load("res://tests/helpers/sw11e_s3_scen.gd")
return H.window_id()

var main = tree.current_scene
var H = load("res://tests/helpers/sw11e_s3_scen.gd")
return H.decider()

var main = tree.current_scene
var H = load("res://tests/helpers/sw11e_s3_scen.gd")
return main.get_tree().root.get_node("StratagemDialog/Content/Header").text.to_lower().contains("selected to fight")

var main = tree.current_scene
var H = load("res://tests/helpers/sw11e_s3_scen.gd")
return H.flag("U_LOGAN_GRIMNAR_A", "sw11e_champions_guidance")

var main = tree.current_scene
var H = load("res://tests/helpers/sw11e_s3_scen.gd")
return H.log_count("Used CHAMPION'S GUIDANCE")

var main = tree.current_scene
var H = load("res://tests/helpers/sw11e_s3_scen.gd")
var u = H.unit("U_LOGAN_GRIMNAR_A")
return (H.codex().apply_hit_bits(0, u, {}, true, []) & 1) == 1 and (H.codex().apply_wound_bits(0, u, {}, true, []) & 1) == 1 and H.codex().apply_hit_bits(0, u, {}, false, []) == 0

var main = tree.current_scene
var H = load("res://tests/helpers/sw11e_s3_scen.gd")
return "U_LOGAN_GRIMNAR_A" in H.phase().units_that_fought

var main = tree.current_scene
var H = load("res://tests/helpers/sw11e_s3_scen.gd")
for b in H.phase().dice_log:
	if typeof(b) == TYPE_DICTIONARY and str(b.get("context", "")) == "hit_roll_melee":
		for e in b.get("modifier_ledger", []):
			if str(e.get("source", "")) == "Champion's Guidance":
				return true
return false

var main = tree.current_scene
var H = load("res://tests/helpers/sw11e_s3_scen.gd")
for b in H.phase().dice_log:
	if typeof(b) == TYPE_DICTIONARY and str(b.get("context", "")) == "wound_roll_melee":
		for e in b.get("modifier_ledger", []):
			if str(e.get("source", "")) == "Champion's Guidance":
				return true
return false
